"""Independent Git/data audit only; no generator, service, or network execution."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[5];H=pathlib.Path(__file__).parent
BASE='bc8b65cc7186e449cf20b4956e4cd88684b35325';SOURCE='e91143dafe2da71546fdfb3b0152807032f4e9b8'
def git(*a):return subprocess.check_output(['git',*a],cwd=R)
def tree(ref):return {p.decode():meta.decode().split()[2] for x in git('ls-tree','-r','-z',ref).split(b'\0') if x for meta,p in [x.split(b'\t',1)]}
def body(ref,path):return git('show',ref+':'+path)
checks=[]
def check(name,value):checks.append({'name':name,'pass':bool(value)});assert value,name
base=tree(BASE);source=tree(SOURCE);current=tree('HEAD')
allowed={'apps/control/document-application/README.md','apps/control/document-application/current.mjs','apps/control/document-application/index.mjs','packages/contracts/README.md','packages/contracts/package.json','packages/contracts/package-lock.json'}
changed={p for p,h in base.items() if source.get(p)!=h};check('exact modified baseline paths, app prerequisite separated',changed==allowed)
check('all other baseline blobs preserved',all(source.get(p)==h for p,h in base.items() if p not in allowed))
