check('package additive0.1.2',new['version']=='0.1.2')
check('old exports exact',all(new['exports'].get(k)==v for k,v in old['exports'].items()))
check('two new public exports only',set(new['exports'])-set(old['exports'])=={'./document-application','./document-application/schema'})
check('dependency pins and engines exact',all(new[k]==old[k] for k in ['dependencies','devDependencies','engines','files']))
a=json.loads(body(BASE,'packages/contracts/package-lock.json'));b=json.loads(body(SOURCE,'packages/contracts/package-lock.json'))
b['version']=a['version'];b['packages']['']['version']=a['packages']['']['version'];check('lock version-only change',a==b)
