for row in meta['sources']:
 p=(R/'packages/contracts'/row['path']).resolve().relative_to(R).as_posix();raw=body(SOURCE,p);check('canonical metadata '+p,len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256'])
check('standalone schema identity',hashlib.sha256(body(SOURCE,'packages/contracts/dist/document-application.schema.json')).hexdigest()==meta['schemaSha256'])
