record={'verdict':'ACCEPT_SOURCE','source':SOURCE,'baseline':BASE,'baselineEntries':len(base),'unchangedBaselineEntries':len(base)-len(changed),'productPaths':products,'checks':checks,'passed':len(checks),'failed':0,'publicTar':pack['tar'],'limits':['Shape/brand/hash admission is not authentication or current authority.','Only synthetic local generation; no Office/render/runtime qualification.','Transport must prevent redirects itself; receiver rejects already-followed responses.']}
(H/'source-audit.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'passed':len(checks),'failed':0,'baselineEntries':len(base),'unchangedBaselineEntries':len(base)-len(changed)}))
